/** Loads the land dot lat/lon pairs generated by scripts/build-geo.mjs. Cached. */
let promise: Promise<Float32Array> | null = null;

export function loadLandDots(): Promise<Float32Array> {
  if (!promise) {
    promise = fetch("/media/geo/land-dots.bin")
      .then((r) => {
        if (!r.ok) throw new Error(`land dots ${r.status}`);
        return r.arrayBuffer();
      })
      .then((buf) => {
        const i16 = new Int16Array(buf);
        const out = new Float32Array(i16.length);
        for (let i = 0; i < i16.length; i++) out[i] = i16[i] / 100;
        return out;
      })
      .catch((e) => {
        promise = null;
        throw e;
      });
  }
  return promise;
}

/** lat/lon in degrees to a point on a sphere. lon 0 faces +z. */
export function latLonToVec(lat: number, lon: number, r: number): [number, number, number] {
  const la = (lat * Math.PI) / 180;
  const lo = (lon * Math.PI) / 180;
  return [r * Math.cos(la) * Math.sin(lo), r * Math.sin(la), r * Math.cos(la) * Math.cos(lo)];
}
